contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: amount to deposit, amount to attempt to collect, and MinSum to set.
    // This function will set up MinSum and Log (addresses), initialize, perform a deposit, then try Collect.
    function run(uint depositAmt, uint collectAmt, uint minSum, address logAddr) public payable {
        require(address(this).balance >= depositAmt, "need funds for deposit");

        // Configure MinSum and Log before initialization
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        // finish initialization so further Set* calls are blocked
        c.Initialized();

        // record observed balances before actions
        uint beforeHolder = c.balances(address(this));
        uint beforeContract = address(c).balance;

        // perform deposit by sending Ether to c
        c.Deposit{value: depositAmt}();

        uint afterDepositHolder = c.balances(address(this));
        uint afterDepositContract = address(c).balance;

        // sanity: deposit must have increased holder & contract balances by depositAmt
        // (we don't assert here; just proceed to try Collect)

        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalHolder = c.balances(address(this));
        uint finalContract = address(c).balance;

        // General invariant rule:
        // If Collect did not revert then holder's balance decreased by collectAmt and contract balance decreased by collectAmt.
        // If Collect reverted then both balances remain as afterDeposit.
        assert(
            (!reverted && finalHolder + collectAmt == afterDepositHolder && finalContract + collectAmt == afterDepositContract)
            || (reverted && finalHolder == afterDepositHolder && finalContract == afterDepositContract)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will parametrize: initialDeposit, minSum, collectAmount
    // The test deposits initialDeposit (by calling Deposit with value), sets MinSum, then attempts Collect.
    // It asserts that if Collect did not revert and the preconditions for sending were met, then
    // c.balances[this] decreased by collectAmount and address(c).balance decreased by collectAmount.

    function run(uint initialDeposit, uint minSum, uint collectAmount) public payable {
        // ensure this contract has enough balance to deposit
        require(address(this).balance >= initialDeposit);

        // Initialize MinSum and Log only while not initialized
        c.SetMinSum(minSum);

        // Record balances before deposit
        uint bal_before_contract = address(c).balance;
        uint bal_before_self = c.balances(address(this));

        // Make a deposit into c from this contract
        c.Deposit{value: initialDeposit}();

        // After deposit, record balances before Collect
        uint bal_after_deposit_contract = address(c).balance;
        uint bal_after_deposit_self = c.balances(address(this));

        // Now attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect attempt
        uint bal_final_contract = address(c).balance;
        uint bal_final_self = c.balances(address(this));

        // Determine whether the contract's Collect should have been allowed by its internal if:
        // Condition used inside Collect: balances[msg.sender] >= MinSum && balances[msg.sender] >= _am
        // We observe balances just before the Collect call as bal_after_deposit_self and MinSum via getter.
        uint observed_balance_before_collect = bal_after_deposit_self;
        uint observed_min_sum = c.MinSum();

        bool should_allow = (observed_balance_before_collect >= observed_min_sum) && (observed_balance_before_collect >= collectAmount);

        // General rule to assert:
        // If Collect reverted then either should_allow was false or the call failed during external transfer; however we only assert the necessary invariant when it succeeded:
        // If Collect did NOT revert and should_allow is true, then c.balances[this] decreased by exactly collectAmount
        // and address(c).balance decreased by exactly collectAmount.
        assert(reverted || !should_allow || (bal_final_self + collectAmount == bal_after_deposit_self && bal_final_contract + collectAmount == bal_after_deposit_contract));
    }

    // allow receiving Ether if c sends funds back to this contract during Collect
    receive() external payable { }
}

