contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint minSum, uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt + 1 wei);
        // Initialize C: set MinSum and a Log, then mark initialized
        c.SetMinSum(minSum);
        // SetLogFile expects an address of a LogFile; reuse address(0) is allowed because LogFile methods are not called in this test path
        c.SetLogFile(address(0));
        c.Initialized();

        // Ensure starting observations
        uint beforeBalRecorded = c.balances(address(this));
        uint beforeContractEth = address(c).balance;
        uint beforeThisEth = address(this).balance;

        // Make a deposit to C from this contract (sends depositAmt wei)
        // depositAmt may be zero
        c.Deposit{value: depositAmt}();

        // Snapshot after deposit
        uint afterBalRecorded = c.balances(address(this));
        uint afterContractEth = address(c).balance;
        uint afterThisEth = address(this).balance;

        // Now attempt Collect of collectAmt wei
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalBalRecorded = c.balances(address(this));
        uint finalContractEth = address(c).balance;
        uint finalThisEth = address(this).balance;

        // If Collect succeeded, then recorded balance must have decreased by collectAmt
        // and this contract's Ether must have increased by collectAmt, and contract's balance decreased by collectAmt.
        // If Collect reverted then no of these three values changed between the post-deposit snapshot and final values.
        assert(
            (!reverted &&
                finalBalRecorded + collectAmt == afterBalRecorded &&
                finalThisEth == afterThisEth + collectAmt &&
                finalContractEth + collectAmt == afterContractEth
            ) || (
                reverted &&
                finalBalRecorded == afterBalRecorded &&
                finalThisEth == afterThisEth &&
                finalContractEth == afterContractEth
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: minSum to configure contract, dep to deposit, col to attempt collect
    function run(uint minSum, uint dep, uint col) public payable {
        // need enough ETH to send dep
        require(address(this).balance >= dep);

        // initialize contract so Deposit/Collect are enabled
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // record before values
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // make a deposit (may be zero)
        c.Deposit{value: dep}();

        // snapshot after deposit and before collect
        uint afterRecorded = c.balances(address(this));
        uint afterContractEth = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value:0}(col) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalRecorded = c.balances(address(this));
        uint finalContractEth = address(c).balance;

        // General rule:
        // - If Collect reverted: neither the recorded balance nor the contract's ETH increased compared to the post-deposit snapshot.
        // - If Collect succeeded: the recorded balance strictly decreased (finalRecorded < afterRecorded) and the contract's ETH decreased (finalContractEth < afterContractEth).
        // This avoids exact equality requirements (which can fail on failed external call edge cases) but enforces that a successful Collect must reduce both stored and on-chain balances, while a revert cannot increase them.
        assert(
            (reverted && finalRecorded <= afterRecorded && finalContractEth <= afterContractEth)
            ||
            (!reverted && finalRecorded < afterRecorded && finalContractEth < afterContractEth)
        );
    }

    // allow receiving ETH from C during Collect
    receive() external payable {}
}

