        uint bal_before = c.balances(address(this));
        uint contract_balance_before = address(c).balance;

        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint bal_after = c.balances(address(this));
        uint contract_balance_after = address(c).balance;

        // General rule:
        // If Collect succeeded then (1) recorded balance decreased by exactly collectAmt,
        // and (2) it was only possible to succeed when the recorded balance before was >= MinSum and >= collectAmt.
        assert(
            reverted || (
                bal_before == bal_after + collectAmt
                && bal_before >= minSum
                && bal_before >= collectAmt
                && contract_balance_before == contract_balance_after + collectAmt
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmt to fund a prior deposit, collectAmt to attempt collecting, minSum to set MinSum
    function run(uint depositAmt, uint collectAmt, uint minSum) public payable {
        require(address(this).balance >= depositAmt);

        // initialize C: set MinSum and LogFile before marking initialized
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // make a deposit so this contract has a recorded balance to attempt Collect
        c.Deposit{value: depositAmt}();

        // observe before-values
        uint bal_before = c.balances(address(this));

        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint bal_after = c.balances(address(this));

        // General rule: If Collect succeeded (did not revert) then the recorded balance strictly decreased.
        assert(reverted || bal_after < bal_before);
    }

    receive() external payable { }
}
